.chat-detail-screen .msg-videocall-card.missed::after {
  opacity: 0.45 !important;
}

/* 语音通话卡片中间文字排版 */
.chat-detail-screen .msg-videocall-card > div:last-of-type {
  display: flex !important;
  flex-direction: column !important;
